// Using enum ensures true compile-time constants in standard C
enum Constants {
    BASE_DIMENSION = 8,
    HEADER_SIZE = 16,
    TOTAL_ITEMS = BASE_DIMENSION * 4
};

// Array size defined by a constant expression evaluated at compile time
int storage_unit[TOTAL_ITEMS];

// A static buffer definition
static unsigned char network_buffer[HEADER_SIZE];

void setup_data(void) {
    // Local scope array sizing
    int metadata[BASE_DIMENSION + 2];
    metadata[0] = 0;
}
